import io.github.vmzakharov.ecdataframe.dsl.*;
import io.github.vmzakharov.ecdataframe.dsl.value.StringValue;
import io.github.vmzakharov.ecdataframe.dsl.visitor.PrettyPrintVisitor;

import io.github.vmzakharov.ecdataframe.util.Printer;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

public class PrettyPrintVisitorTest {

    @Test
    public void visitAssignExprTest() {
        Printer printer = Mockito.mock(Printer.class);
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        AssingExpr expr = new AssingExpr(new VarExpr("variable"), new StringValue("value"));

        visitor.visitAssignExpr(expr);
        Mockito.verify(printer).print("variable = 'value'");
    }

    @Test
    public void exprToStringTest() {
        StringValue value = new StringValue("value");
        String result = PrettyPrintVisitor.exprToString(value);
        Assert.assertEquals("'value'", result);
    }

    @Test
    public void visitBinaryExprTest() {
        Printer printer = Mockito.mock(Printer.class);
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        BinaryExpr expr = new BinaryExpr(new VarExpr("variable"), Operator.EQ, new StringValue("value"));

        visitor.visitBinaryExpr(expr);
        Mockito.verify(printer).print("variable == 'value'");
    }

    @Test
    public void visitUnaryExprTest() {
        Printer printer = Mockito.mock(Printer.class);
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        UnaryExpr expr = new UnaryExpr(Operator.NOT, new VarExpr("variable"));

        visitor.visitUnaryExpr(expr);
        Mockito.verify(printer).print("! variable");
    }

    @Test
    public void visitConstExprTest() {
        Printer printer = Mockito.mock(Printer.class);
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        StringValue value = new StringValue("value");

        visitor.visitConstExpr(value);
        Mockito.verify(printer).print("'value'");
    }

